<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();$db=fleet_db();$id=(int)($_GET['id']??0);$q=$db->prepare('SELECT id,document_storage_name,original_filename,mime_type,status FROM certificate_submissions WHERE id=?');$q->execute([$id]);$c=$q->fetch();if(!$c||$c['status']==='WITHDRAWN'||(string)$c['document_storage_name']===''){http_response_code(404);exit('Document unavailable');}$path='C:/xampp/secure/fleet/certificates/'.basename((string)$c['document_storage_name']);if(!is_file($path)){http_response_code(404);exit('Document unavailable');}
